const srk = (env.SUPABASE_SERVICE_ROLE_KEY || '').trim();
const sb = (env.SUPABASE_URL || '').replace(/\/+$/, '');
const wireKeyRaw = (env.IVX_WIRE_ENCRYPTION_KEY || '').trim();
console.log('IVX_WIRE_ENCRYPTION_KEY set on Render:', Boolean(wireKeyRaw));

