const SH = { apikey: srk, Authorization: `Bearer ${srk}`, Accept: 'application/json' };

function dec(encoded) {
  if (!encoded) return '';
  for (const key of keyCandidates) {
    try {
      const p = JSON.parse(encoded);
      const d = crypto.createDecipheriv('aes-256-gcm', key, Buffer.from(p.iv, 'base64'));
      d.setAuthTag(Buffer.from(p.tag, 'base64'));
      return Buffer.concat([d.update(Buffer.from(p.ct, 'base64')), d.final()]).toString('utf8');
    } catch { /* try next key */ }
  }
  return '<DECRYPT_FAILED>';
